package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
/** Personally harvested fungible timber plus native permanent delivery; no client tally or placed-log credit. */
public final class MasterTimberDelivery {
 public static final String QUEST="kingdom_smp:lumberjack/m02";
 private MasterTimberDelivery(){}
 public static String species(String item){if(!item.startsWith("minecraft:")||!item.endsWith("_log"))return null;String name=item.substring(10,item.length()-4);if(name.startsWith("stripped_"))name=name.substring(9);return TreeEvidence.SPECIES.contains(name)?name:null;}
 public static void goal(int total){if(total<8||total>2304||total%8!=0)throw new IllegalArgumentException("Timber total must be8..2304 in multiples of8; four species each supply at least one eighth");}
 public static Map<String,Integer> select(Map<String,Integer> available,Map<String,Integer> harvested,int total){goal(total);Map<String,Integer> capacity=new TreeMap<>();for(var species:TreeEvidence.SPECIES){int stock=available.getOrDefault(species,0),nativeCount=harvested.getOrDefault(species,0);if(stock<0||nativeCount<0)throw new IllegalArgumentException("Negative timber evidence");capacity.put(species,Math.min(stock,nativeCount));}var qualified=capacity.entrySet().stream().filter(e->e.getValue()>=total/8).sorted(Map.Entry.<String,Integer>comparingByValue().reversed().thenComparing(Map.Entry.comparingByKey())).limit(4).toList();if(qualified.size()!=4)throw new IllegalStateException("Bring personally harvested timber from four species, each at least "+total/8+" logs");Map<String,Integer> result=new TreeMap<>();qualified.forEach(e->result.put(e.getKey(),total/8));int remaining=total/2;for(var entry:capacity.entrySet()){int take=Math.min(remaining,entry.getValue()-result.getOrDefault(entry.getKey(),0));if(take>0){result.merge(entry.getKey(),take,Math::addExact);remaining-=take;}}if(remaining!=0)throw new IllegalStateException("Native harvest and current plain timber inventory must both cover "+total+" logs");return Map.copyOf(result);}
 public static Map<String,Integer> resolve(ServerPlayer p,List<ItemStack> inventory,int total){Map<String,Integer> available=new HashMap<>(),harvested=new HashMap<>();var proof=TreeSavedData.get(p.server).evidence().evidence();for(var kind:TreeEvidence.SPECIES)harvested.put(kind,proof.count(p.getUUID(),ProfessionRank.MASTER,kind));for(var stack:inventory)if(!stack.isEmpty()&&ItemStack.isSameItemSameComponents(stack,new ItemStack(stack.getItem()))){var kind=species(BuiltInRegistries.ITEM.getKey(stack.getItem()).toString());if(kind!=null)available.merge(kind,stack.getCount(),Math::addExact);}var selected=new HashMap<>(select(available,harvested,total));Map<String,Integer> result=new HashMap<>();for(var stack:inventory){if(stack.isEmpty()||!ItemStack.isSameItemSameComponents(stack,new ItemStack(stack.getItem())))continue;String item=BuiltInRegistries.ITEM.getKey(stack.getItem()).toString(),kind=species(item);if(kind==null)continue;int take=Math.min(stack.getCount(),selected.getOrDefault(kind,0));if(take>0){result.merge(item,take,Math::addExact);selected.put(kind,selected.get(kind)-take);}}if(selected.values().stream().anyMatch(n->n!=0))throw new IllegalStateException("Timber inventory changed");return Map.copyOf(result);}
 public static boolean ready(ServerPlayer p,int total){List<ItemStack> inventory=new ArrayList<>();for(int i=0;i<36;i++)inventory.add(p.getInventory().getItem(i));try{resolve(p,inventory,total);return true;}catch(IllegalStateException notReady){return false;}}
 public static int validate(Map<String,Integer> inputs){Map<String,Integer> species=new HashMap<>();int sum=0;for(var entry:inputs.entrySet()){var kind=species(entry.getKey());if(kind==null||entry.getValue()<1||entry.getValue()>2304)throw new IllegalArgumentException("Invalid structural timber input");species.merge(kind,entry.getValue(),Math::addExact);sum=Math.addExact(sum,entry.getValue());}goal(sum);int total=sum;if(species.values().stream().filter(n->n>=total/8).count()<4)throw new IllegalArgumentException("Four native timber species must meet their quotas");return sum;}
}
